Available A2UI catalog:
- football_catalog
  Extends the basic catalog with all standard components plus:
  - Chart:
    {
      "type": "object",
      "properties": {
        "chartType": {
          "type": "string",
          "enum": [
            "bar",
            "line",
            "pie",
            "radar",
            "heatmap"
          ],
          "description": "bar|line: rankings/trends. pie: parts of a whole. radar: one entity across several metrics. heatmap: value across two categories."
        },
        "title": {
          "type": "string",
          "description": "Short chart title."
        },
        "xKey": {
          "type": "string",
          "description": "For bar/line/pie/radar: the key holding the category/axis label in each data item (usually 'name'). Ignored for heatmap."
        },
        "yKeys": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Numeric keys to plot. bar/line: one or more series (e.g. ['value'] or ['goals','assists']). pie: the first key. radar: ONE key per entity — use several to compare entities (e.g. ['mbappe','messi']). Ignored for heatmap."
        },
        "data": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": {
              "type": [
                "string",
                "number"
              ]
            }
          },
          "description": "The data points (max 10). Shape depends on chartType:\n- bar/line/pie: [{\"name\":\"Mbappé\",\"value\":10}, ...].\n- radar: each item is ONE axis/metric; add one numeric key per entity, e.g. [{\"name\":\"Buts\",\"mbappe\":10,\"messi\":8}, {\"name\":\"Minutes\",\"mbappe\":698,\"messi\":740}] with yKeys=['mbappe','messi'].\n- heatmap: [{\"x\":\"Group stage\",\"y\":\"France\",\"value\":10}, ...] with x, y (categories) and value (number)."
        }
      },
      "required": [
        "chartType",
        "data"
      ],
      "additionalProperties": false,
      "$schema": "http://json-schema.org/draft-07/schema#"
    }
